// Only process if we have new tasks
if (!Array.isArray($input.all()) || $input.all().length === 0) {
  return [];
}

const results = [];
for (const item of $input.all()) {
  if (item.json && Array.isArray(item.json)) {
    for (const task of item.json) {
      // Check if task was created in last 2 minutes and doesn't have analysis tag
      const createdTime = new Date(task.created_date);
      const now = new Date();
      const timeDiff = (now - createdTime) / 1000 / 60; // minutes

      const hasAnalysisTag = task.tags && task.tags.some(tag => 
        tag.includes('auto-analyzed') || tag.includes('human-review')
      );

      if (timeDiff <= 2 && !hasAnalysisTag) {
        results.push({
          json: {
            task_id: task.id,
            project_id: task.project,
            user_id: task.assigned_to,
            title: task.subject || 'Task',
            description: task.description || '',
            status: task.status_extra_info?.name || 'New',
            created_date: task.created_date,
            analysis_prompt: `Analyze this task: "${task.subject}". Description: "${task.description}". Determine if it needs human attention and suggest subtasks.`
          }
        });
      }
    }
  }
}

return results;

const taskData = $json;
const llmResponse = $json.choices?.[0]?.message?.content || '{}';

// Clean up the LLM response - remove any markdown formatting
let cleanResponse = llmResponse.trim();
if (cleanResponse.startsWith('```json')) {
  cleanResponse = cleanResponse.replace(/^```json\s*/, '').replace(/\s*```$/, '');
}
if (cleanResponse.startsWith('```')) {
  cleanResponse = cleanResponse.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let analysis;
try {
  analysis = JSON.parse(cleanResponse);
} catch (e) {
  console.log('Failed to parse LLM response:', cleanResponse);
  analysis = {
    needs_human: true,
    reason: 'Analysis failed - needs human review',
    subtasks: ['Review and clarify task requirements', 'Break down into actionable steps']
  };
}

// Ensure subtasks is always an array
if (!Array.isArray(analysis.subtasks)) {
  analysis.subtasks = ['Review task requirements'];
}

return {
  json: {
    task_id: taskData.task_id,
    project_id: taskData.project_id,
    user_id: taskData.user_id,
    title: taskData.title,
    description: taskData.description,
    needs_human: analysis.needs_human,
    reason: analysis.reason,
    subtasks: analysis.subtasks
  }
};

// Create multiple subtasks for human review path
const results = [];
const data = $json;

// Main human review task
results.push({
  json: {
    project: data.project_id,
    subject: `🚨 NEEDS REVIEW: ${data.title}`,
    description: `**HUMAN ATTENTION REQUIRED**\n\nOriginal Task: ${data.title}\n\nReason: ${data.reason}\n\nNext Steps Required:\n${data.subtasks.map(task => `• ${task}`).join('\n')}\n\n⚠️ Please review and break this down further.`,
    assigned_to: data.user_id,
    tags: ['human-review', 'urgent', 'auto-generated'],
    priority: 3
  }
});

// Create individual subtasks
for (let i = 0; i < data.subtasks.length; i++) {
  results.push({
    json: {
      project: data.project_id,
      subject: `📋 Subtask ${i + 1}: ${data.subtasks[i]}`,
      description: `**AUTO-GENERATED SUBTASK**\n\nParent Task: ${data.title}\n\nAction Required: ${data.subtasks[i]}\n\nThis task was automatically created based on AI analysis.`,
      assigned_to: data.user_id,
      tags: ['subtask', 'auto-generated', 'human-review'],
      priority: 2
    }
  });
}

return results;

// Create automated subtasks for simple tasks
const results = [];
const data = $json;

// Main completion task  
results.push({
  json: {
    project: data.project_id,
    subject: `✅ READY: ${data.title}`,
    description: `**AUTO-ANALYSIS COMPLETE**\n\nTask: ${data.title}\n\nAI Analysis: ${data.reason}\n\nRecommended Actions:\n${data.subtasks.map(task => `• ${task}`).join('\n')}\n\n🤖 This task has been pre-analyzed and is ready for execution.`,
    assigned_to: data.user_id,
    tags: ['auto-analyzed', 'ready', 'auto-generated'],
    priority: 1
  }
});

// Create action items
for (let i = 0; i < data.subtasks.length; i++) {
  results.push({
    json: {
      project: data.project_id,
      subject: `⚡ Action ${i + 1}: ${data.subtasks[i]}`,
      description: `**AUTO-GENERATED ACTION ITEM**\n\nParent Task: ${data.title}\n\nAction: ${data.subtasks[i]}\n\nThis is ready to execute based on AI analysis.`,
      assigned_to: data.user_id,
      tags: ['action-item', 'auto-generated', 'ready'],
      priority: 1
    }
  });
}

return results;
